export function isValidChoices(a){return Array.isArray(a)&&a.length===4&&a.every((v,i)=>v===null||seasons[i].choices.some(c=>c.id===v));}
export function damage(a){return [a[0]==='cut',a[1]==='hide',a[2]==='spray',a[3]==='burn'].filter(Boolean).length;}
export function resolveEnding(a,repair=false){
  if(!isValidChoices(a)||a.some(x=>x===null))throw new Error('네 계절의 선택이 모두 필요합니다.');
  const [s,w,f,l]=a, d=damage(a);
  if(repair&&(d>0||s==='garden'||f==='garden'||f==='wait'||w!=='treat'||l!=='reuse'))return 'E10';
  if(d>=3||(w==='hide'&&d>=2))return 'E09';
  if(s==='cut')return 'E08';
  if(s==='garden'||f==='garden')return 'E07';
  if(w==='hide'||f==='spray'||l==='burn')return 'E06';
  if(s==='corridor'&&w==='treat'&&f==='care'&&l==='reuse')return 'E01';
  if(s==='detour'&&w==='treat'&&f==='care'&&l==='reuse')return 'E02';
  if(w==='treat'&&f==='wait')return 'E03';
  if(l==='reuse')return 'E05';
  if(f==='care'&&w==='treat')return 'E04';
  return 'E06';
}
